-- ============================================================
-- INSERT COMMANDS CHO MODULE QUẢN LÝ NHÂN SỰ (SisHr)
-- Ma_phan_he = 'HR', is_mobile = '2' (Blazor web)
-- Menu_id pattern: wr.xx.xx  (w=web, r=HR)
-- ============================================================
-- 
-- GHI CHÚ CẤU TRÚC DATABASE:
-- Tất cả các danh mục từ điển dùng chung bảng dmhrtd với khóa (loai_td, ma_td)
-- loai_td map:
--   1=Bộ phận NS, 2=Xếp loại LĐ, 3=Chức vụ, 4=XL bằng cấp, 5=Trình độ VH
--   6=TT sức khỏe, 7=TT hôn nhân, 8=TT hợp đồng, 9=Tỉnh thành, 10=TP xã hội
--   11=Trình độ TH, 12=Tôn giáo, 13=QH gia đình, 14=Quốc gia, 15=Ngoại ngữ
--   16=Nơi KCB, 17=Nơi cấp thẻ BH, 18=Nơi công tác, 19=Chứng chỉ
--   20=KT kỷ luật, 21=Khả năng, 22=Huyện, 23=Hình thức ĐT, 24=Giới tính
--   25=Dân tộc, 27=Chính sách, 28=Chuyên ngành, 29=Chức danh
--   30=Nơi cấp sổ BHXH, 31=Trình độ
--
-- SQL TẠO BẢNG:
-- IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='dmhrtd' AND xtype='U')
-- CREATE TABLE dmhrtd (
--     loai_td   INT           NOT NULL,
--     ma_td     VARCHAR(20)   NOT NULL,
--     ten_td    NVARCHAR(150) NULL,
--     ten_td2   NVARCHAR(150) NULL,
--     ma_tra_cuu VARCHAR(50)  NULL,
--     status    VARCHAR(1)    NULL DEFAULT '1',
--     date      SMALLDATETIME NULL,
--     time      VARCHAR(8)    NULL,
--     user_id   INT           NULL,
--     user_name NVARCHAR(50)  NULL,
--     date0     SMALLDATETIME NULL,
--     time0     VARCHAR(8)    NULL,
--     user_id0  INT           NULL,
--     user_name0 NVARCHAR(50) NULL,
--     search    NVARCHAR(250) NULL,
--     CONSTRAINT PK_dmhrtd PRIMARY KEY (loai_td, ma_td)
-- );
-- ============================================================

-- 1. XÓA DỮ LIỆU CŨ
DELETE FROM [command]
WHERE menu_id LIKE 'wr.%'
  AND ma_phan_he = 'HR'
  AND is_mobile = '2';

